# Gemeinsame Hilfsregeln für die ÖPUL-Maßnahme
# "Einschränkung ertragssteigernder Betriebsmittel" (o6_2, SRL-Maßnahme 2).
package oepul.o6_2

lists := data.o6_2_lists

general := data.o6_2_general

premium_data := data.o6_2_premium

rgve_data := data.o6_2_rgve

combos := data.o6_2_combinations

drought := data.o6_2_drought_2026

year := input.farm.year

parcels := object.get(input, ["land", "parcels"], [])

oepul := object.get(input, ["farm", "oepul"], {})

o6_2_state := object.get(oepul, "o6_2", {})

participating_measures := {m | some m in object.get(oepul, "participating_measures", [])}

crop_name_of(p) := lower(object.get(p, ["crop", "crop_name"], "")) if {
	object.get(p, ["crop", "crop_name"], null) != null
} else := ""

oepul_codes_of(p) := {c | some c in object.get(p, "oepul_codes", [])}

# Parzellen außerhalb Österreichs werden nicht gefördert und nicht berücksichtigt.
parcel_in_austria(p) if object.get(p, "is_in_austria", true) == true

# Ackerfutterkulturen gemäß Definition (Futtergräser, Wechselwiese, Kleegras,
# Klee, Luzerne, Sonstiges Feldfutter, Ackerweide).
is_arable_forage_crop(p) if {
	p.land_use == "arable"
	some c in lists.arable_forage_crops
	lower(c) == crop_name_of(p)
}

forage_as_second_crop(p) if object.get(p, ["crop", "forage_as_second_crop"], false) == true

# Ackerfutter als Hauptkultur (Zweitkultur zählt als Ackerfläche).
is_arable_forage_main(p) if {
	is_arable_forage_crop(p)
	not forage_as_second_crop(p)
}

is_fruit_crop(p) if {
	some c in lists.fruit_crops
	lower(c) == crop_name_of(p)
}

is_fruit_crop(p) if {
	year >= 2025
	some c in lists.fruit_crops_from_2025
	lower(c) == crop_name_of(p)
}

is_wine_fruit_hop(p) if {
	p.land_use == "special_crop"
	p.crop.crop_category in {"vineyard", "hop"}
}

is_wine_fruit_hop(p) if {
	p.land_use == "special_crop"
	p.crop.crop_category == "orchard"
	is_fruit_crop(p)
}

# Prämienkategorie einer Parzelle gemäß Kapitel 7 des Informationsblatts.
parcel_category(p) := "arable_forage" if {
	is_arable_forage_main(p)
} else := "arable" if {
	p.land_use == "arable"
} else := "grassland" if {
	p.land_use == "grassland"
} else := "wine_fruit_hop" if {
	is_wine_fruit_hop(p)
} else := "not_eligible"

# Futterfläche = Grünland + Ackerfutterflächen (ohne Ackerfutter als Zweitkultur),
# unabhängig davon, in welche Maßnahme die Fläche eingebracht ist.
is_fodder_area(p) if {
	parcel_in_austria(p)
	p.land_use == "grassland"
}

is_fodder_area(p) if {
	parcel_in_austria(p)
	is_arable_forage_main(p)
}

# Grünland- und Ackerfutterflächen für das Pflanzenschutzmittelverbot
# (tatsächliche Kultur, auch bei Beantragung als Zweitkultur).
is_psm_restricted_area(p) if p.land_use == "grassland"

is_psm_restricted_area(p) if is_arable_forage_crop(p)

agricultural_area_ha := sum([p.area_ha |
	some p in parcels
	parcel_in_austria(p)
	p.land_use != "alpine_pasture"
])

total_farm_area_ha := input.land.total_area_ha if {
	input.land.total_area_ha > 0
} else := agricultural_area_ha

# Vertragszeitraum, Ausstieg, Maßnahmenwechsel, Flächenab- und -zugänge,
# Maßnahmenübernahme (Allg. Teilnahmebedingungen 5.8-7.2, SRL 1.7).
package oepul.o6_2

contract_period := cp if {
	some cp in general.contract_periods
	cp.start_year == contract_start_year
}

contract_end_date := "2028-12-31"

exit_info := object.get(o6_2_state, "exit", {})

exit_date := object.get(exit_info, "exit_date", null)

exit_reason := object.get(exit_info, "reason", "none")

switched_to_bio_date := object.get(o6_2_state, "switched_to_bio_date", null)

# Umstieg in "Biologische Wirtschaftsweise" bis 31.12.2025 ohne Rückzahlung.
switch_to_bio_without_repayment if {
	switched_to_bio_date != null
	switched_to_bio_date <= combos.measure_switch_deadline
}

repayment_free_exit_reasons := {"loss_of_control", "revision_clause_refusal", "permanent_circumstances"}

exit_before_contract_end if {
	exit_date != null
	exit_date < contract_end_date
}

# Ausstieg vor Ende des Vertragszeitraums: Rückforderung aller bisher gewährten Prämien.
repayment_of_all_premiums_required if {
	exit_before_contract_end
	not exit_reason in repayment_free_exit_reasons
	not switch_to_bio_without_repayment
}

repayment_of_all_premiums_required if excluded_from_measure

# Zahlungsantrag nicht innerhalb 1 Jahr nachgereicht: Verpflichtung endet, Rückzahlung.
repayment_of_all_premiums_required if {
	object.get(o6_2_state, "payment_application_missing_over_one_year", false) == true
}

# Betriebsübertragung: Nachfolger tritt dem Vertrag bei, Flächen weiterführen.
farm_transfer_continues_contract if exit_reason == "farm_transfer"

# Flächenabgang: Toleranz max(0,5 ha; min(5 % Vorjahresfläche; 5 ha)).
previous_year_area_ha := object.get(o6_2_state, "previous_year_committed_area_ha", 0)

area_reduction_ha := object.get(o6_2_state, "area_reduction_ha", 0)

area_decrease_tolerance_ha := max([
	general.area_decrease_tolerance.always_allowed_ha_per_year,
	min([
		(previous_year_area_ha * general.area_decrease_tolerance.max_percent_of_previous_year) / 100,
		general.area_decrease_tolerance.max_ha_per_year,
	]),
])

area_decrease_repayment_ha := area_reduction_ha if {
	area_reduction_ha > area_decrease_tolerance_ha
} else := 0

conversion_allowed(from_code, to_code) if {
	some c in general.allowed_land_use_conversions
	from_code in c.from
	to_code in c.to
}

conversion_allowed(_, to_code) if {
	some c in general.allowed_land_use_conversions
	"*" in c.from
	to_code in c.to
}

# Maßnahmenübernahme durch einen bisher nicht teilnehmenden Betrieb.
takeover := object.get(o6_2_state, "takeover", null)

takeover_deadline(y) := sprintf("%d-%s", [y, general.takeover.deadline_month_day_2023_2028]) if {
	y in {2023, 2028}
} else := sprintf("%d-%s", [y, general.takeover.deadline_month_day])

takeover_valid if {
	takeover != null
	takeover.takeover_date <= takeover_deadline(year)
	object.get(takeover, "taker_previously_participating", false) == false
	object.get(takeover, "extension_percent", 0) <= general.takeover.max_extension_percent
}

# Unterjährige Flächenweitergabe ohne Weiterführung: Code OP erforderlich.
parcels_requiring_op_code contains p.parcel_id if {
	some p in parcels
	object.get(p, "transferred_during_year_without_continuation", false) == true
	not "OP" in oepul_codes_of(p)
}

# Verweigerung/Verhinderung der Vor-Ort-Kontrolle: Antrag abzulehnen.
control_refused if object.get(oepul, "on_site_control_refused", false) == true

sanction_percent_for(level_id, y) := lvl.reduction_percent_from_2027 if {
	y >= 2027
	some lvl in general.sanction_levels
	lvl.id == level_id
} else := lvl.reduction_percent if {
	some lvl in general.sanction_levels
	lvl.id == level_id
}

# Teilnahme- und Zugangsvoraussetzungen, Maßnahmenkombination, Beantragung.
package oepul.o6_2

# Zugangsvoraussetzung: zeitgleiche Teilnahme an UBB (1A).
participates_ubb if "1A" in participating_measures

bio_partial_wine_fruit_hop if {
	object.get(oepul, ["bio_partial_farm", "is_partial_farm"], false) == true
	object.get(oepul, ["bio_partial_farm", "bio_culture_area"], null) == "wine_fruit_hop"
}

# Betriebliche Kombination mit Biologischer Wirtschaftsweise (1B) ausgeschlossen,
# ausgenommen Bio-Teilbetrieb mit Kulturbereich Wein, Obst und Hopfen.
bio_combination_conflict if {
	"1B" in participating_measures
	not bio_partial_wine_fruit_hop
}

contract_start_year := object.get(o6_2_state, "contract_start_year", null)

first_commitment_year if year == contract_start_year

access_condition_failures contains "O6_2-ACC-UBB-001" if not participates_ubb

access_condition_failures contains "O6_2-COMB-BIO-001" if bio_combination_conflict

# Förderwerbende Person: Gebietskörperschaften und Einrichtungen mit
# bestimmendem Einfluss (> 25 %) sind in dieser Maßnahme ausgeschlossen.
applicant_type := object.get(oepul, "applicant_type", "natural_person")

applicant_ineligible if applicant_type == "public_body"

applicant_ineligible if {
	applicant_type in {"legal_person", "association"}
	object.get(oepul, "public_body_share_percent", 0) > general.public_body_max_share_percent
}

access_condition_failures contains "O6_2-GEN-APPLICANT-001" if applicant_ineligible

# Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr.
protected_cultivation_area_ha := sum([p.area_ha |
	some p in parcels
	parcel_in_austria(p)
	is_protected_cultivation(p)
])

is_protected_cultivation(p) if object.get(p, "land_use_code", "") == "GA"

is_protected_cultivation(p) if object.get(p, ["crop", "non_eligible_type"], "") == "protected_cultivation"

minimum_farm_size_met if {
	protected_cultivation_area_ha >= general.minimum_farm_size_first_year.protected_cultivation_ha
}

minimum_farm_size_met if {
	sum([p.area_ha | some p in parcels; parcel_in_austria(p)]) >= general.minimum_farm_size_first_year.agricultural_area_ha
}

first_oepul_year if year == object.get(oepul, "first_oepul_participation_year", null)

access_condition_failures contains "O6_2-GEN-MINSIZE-001" if {
	first_oepul_year
	not minimum_farm_size_met
}

# Beantragung: Maßnahmenantrag bis 31.12. vor Vertragsbeginn, letzter Einstieg 2025.
application_date := object.get(o6_2_state, "application_date", null)

valid_contract_start if {
	some cp in general.contract_periods
	cp.start_year == contract_start_year
}

application_timely if {
	valid_contract_start
	application_date != null
	application_date <= sprintf("%d-12-31", [contract_start_year - 1])
	application_date <= general.last_application_date
}

contract_failures contains "O6_2-APP-DEADLINE-001" if not application_timely

contract_failures contains "O6_2-APP-LASTENTRY-001" if {
	contract_start_year != null
	contract_start_year > general.last_entry_year
}

# Folgen nicht erfüllter Zugangsvoraussetzungen (SRL 1.12.1.1):
# im 1. Jahr kommt kein Vertrag zustande, ab dem 2. Jahr keine Prämie im Jahr.
no_contract_due_to_access if {
	first_commitment_year
	count(access_condition_failures) > 0
}

no_premium_this_year_due_to_access if {
	not first_commitment_year
	count(access_condition_failures) > 0
}

contract_valid if {
	count(contract_failures) == 0
	not no_contract_due_to_access
}

# Einzelflächenkombination gemäß Anhang L.
combination_marker(code) := row.marker if {
	some row in combos.single_area_combination_row
	row.measure_code == code
}

single_area_combinable(code) if combination_marker(code) in {"x", "a"}

single_area_premium_reduction(code) if combination_marker(code) == "a"

# Maßnahmen auf einer Parzelle, die prämienmäßig nicht mit o6_2 kombinierbar sind.
parcel_combination_conflicts(p) := {c |
	some c in object.get(p, "parcel_measures", [])
	c != "2"
	not single_area_combinable(c)
}

# Tierhaltereigenschaft, RGVE-Besatz und Stickstoffanfall aus der Tierhaltung.
package oepul.o6_2

rgve_key_by_id := {r.id: r | some r in rgve_data.key}

species_groups := object.get(input, ["livestock", "species_groups"], [])

# Nur in Österreich gehaltene Tiere sind anrechenbar.
group_held_in_austria(g) if object.get(g, "held_in_austria", true) == true

group_rgve(g) := g.animal_count * rgve_key_by_id[g.rgve_key_id].rgve_per_head if {
	group_held_in_austria(g)
	rgve_key_by_id[g.rgve_key_id].rgve_per_head != null
	rgve_key_by_id[g.rgve_key_id].species_group in rgve_data.livestock_farm_species_groups
}

total_rgve := sum([r | some g in species_groups; r := group_rgve(g)])

fodder_area_ha := sum([p.area_ha | some p in parcels; is_fodder_area(p)])

stocking_density_rgve_per_ha := total_rgve / fodder_area_ha if fodder_area_ha > 0

is_livestock_farm if {
	stocking_density_rgve_per_ha >= premium_data.livestock_density_threshold_rgve_per_ha
}

livestock_status := "livestock" if {
	is_livestock_farm
} else := "non_livestock"

rgve_band := "ge_1_4" if {
	stocking_density_rgve_per_ha >= premium_data.premium_band_threshold_rgve_per_ha
} else := "lt_1_4"

# Tiergruppen ohne zuordenbaren RGVE-Schlüssel (Datenlücke im Profil).
unmapped_species_groups contains g.species if {
	some g in species_groups
	g.species in {"cattle", "sheep_goats", "horses", "other"}
	not rgve_key_by_id[object.get(g, "rgve_key_id", "")]
}

# Stickstoffanfall aus der Tierhaltung nach Abzug der Stall- und Lagerverluste;
# auf Almen/Gemeinschaftsweiden angefallener N wird abgezogen, Düngerabnahmeverträge
# werden nicht berücksichtigt.
nitrogen := object.get(input, ["livestock", "nitrogen"], {})

n_attributable_kg := object.get(nitrogen, "n_after_stall_storage_losses_kg", 0) - object.get(nitrogen, "n_on_alm_or_community_pasture_kg", 0)

n_per_ha := n_attributable_kg / agricultural_area_ha if agricultural_area_ha > 0

nitrogen_limit_exceeded if n_per_ha > general.nitrogen_max_kg_per_ha

# Förderverpflichtungen (Kapitel 5 des Informationsblatts, SRL Punkt 2.2.4).
package oepul.o6_2

fertilizer_input_by_id := {f.id: f | some f in lists.fertilizer_inputs}

psm_mode_by_id := {m.id: m | some m in lists.psm_application_modes}

fertilizer_inputs_of(p) := object.get(p, ["operations", "fertilizer", "inputs"], [])

psm_applications_of(p) := object.get(p, ["operations", "psm_applications"], [])

input_is_external(i) if object.get(i, "external_origin", false) == true

fertilizer_status(i) := fertilizer_input_by_id[i.input_id].status_external if {
	input_is_external(i)
} else := fertilizer_input_by_id[i.input_id].status_own_farm

fertilizer_input_prohibited(i) if fertilizer_status(i) == "prohibited"

fertilizer_input_prohibited(i) if {
	fertilizer_status(i) == "allowed_if_return_of_delivered_slurry"
	object.get(i, "is_return_of_delivered_slurry", false) != true
}

# Unbekannte, betriebsfremde, stickstoffhaltige Betriebsmittel gelten als unzulässig.
fertilizer_input_prohibited(i) if {
	not fertilizer_input_by_id[i.input_id]
	input_is_external(i)
	object.get(i, "contains_n", true) == true
}

# 5.1: Verbot betriebsfremder, stickstoffhaltiger Düngemittel auf der gesamten LN
# (auch auf in der Maßnahme nicht prämienfähigen Flächen).
violations contains {
	"rule_id": "O6_2-OBL-N-FERT-001",
	"parcel_id": p.parcel_id,
	"input_id": i.input_id,
	"message": "Unzulässiges stickstoffhaltiges Betriebsmittel ausgebracht",
} if {
	some p in parcels
	some i in fertilizer_inputs_of(p)
	fertilizer_input_prohibited(i)
}

violations contains {
	"rule_id": "O6_2-OBL-N-FERT-002",
	"parcel_id": p.parcel_id,
	"input_id": "mineral_n_fertilizer",
	"message": "Mineralischer Stickstoffdünger ausgebracht",
} if {
	some p in parcels
	object.get(p, ["operations", "fertilizer", "mineral_n_kg_per_ha"], 0) > 0
}

# 5.2: Maximal 170 kg N/ha LN aus der Tierhaltung.
violations contains {
	"rule_id": "O6_2-OBL-N-LIMIT-001",
	"parcel_id": null,
	"input_id": null,
	"message": sprintf("Stickstoffanfall aus der Tierhaltung %.1f kg N/ha > 170 kg N/ha", [n_per_ha]),
} if {
	nitrogen_limit_exceeded
}

psm_counts_as_broadcast(a) := psm_mode_by_id[a.application_mode].counts_as_broadcast

psm_application_prohibited(a) if {
	psm_counts_as_broadcast(a)
	object.get(a, "organic_approved_only", false) != true
}

# 5.3: Kein flächiger PSM-Einsatz auf Ackerfutter- und Grünlandflächen
# (Ausnahme: nur Bio-Wirkstoffe; Einzelpflanzenbehandlung; Beizung = flächig).
violations contains {
	"rule_id": "O6_2-OBL-PSM-001",
	"parcel_id": p.parcel_id,
	"input_id": object.get(a, "product_name", null),
	"message": sprintf("Flächiger Pflanzenschutzmitteleinsatz (%s) auf Grünland/Ackerfutter", [a.application_mode]),
} if {
	some p in parcels
	is_psm_restricted_area(p)
	some a in psm_applications_of(p)
	psm_application_prohibited(a)
}

broadcast_psm_on_restricted(p) if {
	is_psm_restricted_area(p)
	some a in psm_applications_of(p)
	psm_counts_as_broadcast(a)
}

chemical_broadcast_psm_on_restricted(p) if {
	is_psm_restricted_area(p)
	some a in psm_applications_of(p)
	psm_application_prohibited(a)
}

required_psm_code(p) := "PSMCS" if {
	chemical_broadcast_psm_on_restricted(p)
} else := "PSMBIO" if {
	broadcast_psm_on_restricted(p)
}

psm_code_satisfied(p) if required_psm_code(p) in oepul_codes_of(p)

# PSMCS deckt auch zusätzliche Bio-Mittel ab.
psm_code_satisfied(p) if {
	required_psm_code(p) == "PSMBIO"
	"PSMCS" in oepul_codes_of(p)
}

# 5.3: Angabeverpflichtung (PSMBIO/PSMCS) bis einschließlich Antragsjahr 2025.
violations contains {
	"rule_id": "O6_2-OBL-PSM-CODE-001",
	"parcel_id": p.parcel_id,
	"input_id": required_psm_code(p),
	"message": sprintf("Code %s im Mehrfachantrag fehlt", [required_psm_code(p)]),
} if {
	year <= 2025
	some p in parcels
	required_psm_code(p)
	not psm_code_satisfied(p)
}

psm_coding_obligation_applies if year <= 2025

# 5.4: Kauf und Lagerung unzulässiger Betriebsmittel verboten.
operating_supplies := object.get(oepul, "operating_supplies", [])

supply_purchased_or_stored(s) if object.get(s, "purchased", false) == true

supply_purchased_or_stored(s) if object.get(s, "stored", false) == true

psm_supply_exception(s) if {
	object.get(s, "psm_permitted_in_other_crops", false) == true
	object.get(s, "quantity_plausible", false) == true
	object.get(s, "records_available", false) == true
}

supply_inadmissible(s) if {
	s.category == "fertilizer"
	fertilizer_input_prohibited(s)
}

supply_inadmissible(s) if {
	s.category == "psm"
	object.get(s, "organic_approved_only", false) != true
	not psm_supply_exception(s)
}

violations contains {
	"rule_id": "O6_2-OBL-SUPPLY-001",
	"parcel_id": null,
	"input_id": s.input_id,
	"message": "Kauf oder Lagerung eines in der Maßnahme unzulässigen Betriebsmittels",
} if {
	some s in operating_supplies
	supply_purchased_or_stored(s)
	supply_inadmissible(s)
}

# 5.5: Weiterbildung (mind. 3 h Stickstoffdüngung / angepasste Nutzungshäufigkeit).
trainings := object.get(oepul, "trainings", [])

training_creditable(t) if {
	t.topic in general.training.topics
	t.date >= general.training.earliest_creditable_date
	t.date <= general.training.deadline
	object.get(t, "provider_recognized", false) == true
	t.attendee_role in general.training.attendee_roles_allowed
	object.get(t, "credited_to_other_farm", false) != true
	object.get(t, "credited_to_other_commitment", false) != true
	not attendee_left_before_deadline(t)
}

attendee_left_before_deadline(t) if {
	left := object.get(t, "attendee_left_farm_date", null)
	left != null
	left < general.training.deadline
}

creditable_training_hours := sum([t.hours | some t in trainings; training_creditable(t)])

training_requirement_met if creditable_training_hours >= general.training.min_hours

violations contains {
	"rule_id": "O6_2-OBL-TRAIN-001",
	"parcel_id": null,
	"input_id": null,
	"message": sprintf("Anrechenbare Weiterbildung %.1f h < 3 h bis 31.12.2025", [creditable_training_hours]),
} if {
	year >= 2025
	not training_requirement_met
}

# Hinweise, die mangels Detailangaben manuell zu prüfen sind.
review_items contains {
	"rule_id": "O6_2-OBL-PSM-001",
	"parcel_id": p.parcel_id,
	"message": "PSM-Einsatz auf Grünland/Ackerfutter gemeldet, aber ohne Angaben zur Anwendungsart",
} if {
	some p in parcels
	is_psm_restricted_area(p)
	object.get(p, ["operations", "psm_used"], false) == true
	count(psm_applications_of(p)) == 0
}

review_items contains {
	"rule_id": "O6_2-OBL-N-FERT-004",
	"parcel_id": null,
	"message": "Gesetzliche Düngeobergrenzen und Verbotszeiträume sind zusätzlich einzuhalten",
} if {
	count(parcels) > 0
}

# Prämienberechnung (Kapitel 7 Informationsblatt, SRL 2.2.5, allgemeine
# Bestimmungen zu Modulation, Obergrenzen, Flächenzugang).
package oepul.o6_2

rate_for(category, status, band, y) := r.eur_per_ha if {
	some r in premium_data.rates
	r.area_category == category
	r.livestock_status in {"any", status}
	r.rgve_band in {"any", band}
	r.year_from <= y
	y <= r.year_to
}

non_eligible_types := {t.id | some t in lists.non_eligible_crop_types}

national_park_premium_possible(p) if object.get(p, "national_park", null) == null

national_park_premium_possible(p) if {
	some np in general.national_parks
	np.id == p.national_park
	np.o6_2_premium_possible
}

# Gründe, aus denen eine Parzelle keine o6_2-Prämie erhält: [parcel_id, Grund].
parcel_exclusions contains [p.parcel_id, "not_in_austria"] if {
	some p in parcels
	not parcel_in_austria(p)
}

parcel_exclusions contains [p.parcel_id, "not_eligible_category"] if {
	some p in parcels
	parcel_category(p) == "not_eligible"
}

parcel_exclusions contains [p.parcel_id, "non_eligible_crop_type"] if {
	some p in parcels
	object.get(p, ["crop", "non_eligible_type"], null) in non_eligible_types
}

parcel_exclusions contains [p.parcel_id, "protected_cultivation"] if {
	some p in parcels
	is_protected_cultivation(p)
}

parcel_exclusions contains [p.parcel_id, "code_op_or_vf"] if {
	some p in parcels
	has_no_premium_code(p)
}

parcel_exclusions contains [p.parcel_id, "national_park"] if {
	some p in parcels
	not national_park_premium_possible(p)
}

parcel_exclusions contains [p.parcel_id, "fruit_not_quality_planting_material"] if {
	some p in parcels
	fruit_without_quality_material(p)
}

parcel_exclusions contains [p.parcel_id, "glaez8_npf_forage_until_2024"] if {
	some p in parcels
	glaez8_npf_forage_excluded(p)
}

parcel_exclusions contains [p.parcel_id, "minimum_management_not_met"] if {
	some p in parcels
	not minimum_management_met(p)
}

parcel_exclusions contains [p.parcel_id, "single_area_combination_conflict"] if {
	some p in parcels
	count(parcel_combination_conflicts(p)) > 0
}

exclusion_reasons_of(p) := {r | some [pid, r] in parcel_exclusions; pid == p.parcel_id}

has_no_premium_code(p) if {
	some c in general.no_premium_codes
	c in oepul_codes_of(p)
}

fruit_without_quality_material(p) if {
	p.crop.crop_category == "orchard"
	object.get(p, "fruit_quality_planting_material", true) == false
}

# Bis einschließlich 2024 keine Ackerfutterprämie für GLÖZ-8-NPF Klee/Kleegras/Luzerne.
glaez8_npf_forage_excluded(p) if {
	year <= 2024
	object.get(p, ["crop", "glaez8_npf"], false) == true
	some c in lists.glaez8_npf_forage_crops_without_forage_premium_until_2024
	lower(c) == crop_name_of(p)
}

premium_eligible_parcel(p) if count(exclusion_reasons_of(p)) == 0

parcel_rate(p) := rate_for(parcel_category(p), livestock_status, rgve_band, year) if premium_eligible_parcel(p)

parcel_premium_eur := {p.parcel_id: v |
	some p in parcels
	premium_eligible_parcel(p)
	v := parcel_rate(p) * p.area_ha
}

premium_eligible_area_ha := sum([p.area_ha | some p in parcels; premium_eligible_parcel(p)])

gross_premium_eur := sum([v | some v in parcel_premium_eur])

# Inhaltliche Kürzung gemäß festgelegter Sanktionsstufe.
sanction_level := object.get(o6_2_state, ["sanction", "level"], null)

sanction_reduction_percent := sanction_percent_for(sanction_level, year) if {
	sanction_level != null
} else := 0

excluded_from_measure if sanction_level == "exclusion"

excluded_from_measure if object.get(o6_2_state, ["sanction", "full_reductions_in_contract_period"], 0) >= 2

# Betriebsgrößenmodulation.
tier_share(area, t) := max([0, min([area, t.to_ha]) - t.from_ha]) if t.to_ha != null

tier_share(area, t) := max([0, area - t.from_ha]) if t.to_ha == null

modulation_factor(area) := 1 if area <= 0

modulation_factor(area) := sum([v |
	some t in general.modulation_tiers
	v := (tier_share(area, t) * t.payout_percent) / 100
]) / area if {
	area > 0
}

farm_modulation_factor := modulation_factor(total_farm_area_ha)

# Obergrenze der Flächenzahlungen je ha (Summe aller Flächenzahlungen des Schlags).
area_payment_cap_eur_per_ha := c.eur_per_ha if {
	some c in general.area_payment_caps
	c.applies_to == "standard"
	c.year_from <= year
	year <= c.year_to
}

parcel_net_rate(p) := min([
	((parcel_rate(p) * (100 - sanction_reduction_percent)) / 100) * farm_modulation_factor,
	max([0, area_payment_cap_eur_per_ha - object.get(p, "other_area_payments_eur_per_ha", 0)]),
])

parcel_net_premium_eur := {p.parcel_id: v |
	some p in parcels
	premium_eligible_parcel(p)
	v := parcel_net_rate(p) * p.area_ha
}

net_before_access_reduction_eur := sum([v | some v in parcel_net_premium_eur])

# Flächenzugang ab 2026: max. +50 % auf Basis 2025, mind. +5 ha immer zulässig.
area_2025_ha := object.get(o6_2_state, "committed_area_2025_ha", null)

new_area_additions_ha := object.get(o6_2_state, "new_area_additions_ha", 0)

allowed_area_increase_ha := max([
	(area_2025_ha * general.area_increase.max_increase_percent_after_base) / 100,
	general.area_increase.always_allowed_increase_ha,
]) if {
	area_2025_ha != null
}

area_increase_excess_ha := max([0, new_area_additions_ha - allowed_area_increase_ha]) if {
	year > general.area_increase.base_year
} else := 0

average_net_rate := net_before_access_reduction_eur / premium_eligible_area_ha if {
	premium_eligible_area_ha > 0
} else := 0

access_reduction_eur := min([area_increase_excess_ha, premium_eligible_area_ha]) * average_net_rate

premium_granted if {
	contract_valid
	not no_premium_this_year_due_to_access
	not excluded_from_measure
	object.get(o6_2_state, "payment_application_submitted", true) == true
}

net_premium_eur := max([0, net_before_access_reduction_eur - access_reduction_eur]) if {
	premium_granted
} else := 0

payout_may_be_waived if net_premium_eur <= general.payment.min_payout_eur

max_advance_payment_eur := (net_premium_eur * general.payment.max_advance_percent) / 100

